// Avvisa solo al CAMBIO di stato (non-oltre -> oltre soglia), non a ogni giro: niente cooldown da configurare.
const mint = $env.TOKEN_MINT || 'So11111111111111111111111111111111111111112';
const body = $input.first().json;
const voce = (body.data && body.data[mint]) || null;
if (!voce) return [{ json: { scatta: false, errore: 'prezzo non trovato per ' + mint } }];
const prezzo = Number(voce.price);
const soglia = Number($env.SOGLIA_PREZZO || 0);
const direzione = ($env.DIREZIONE || 'sopra').toLowerCase();
const oltre = direzione === 'sotto' ? prezzo <= soglia : prezzo >= soglia;
const state = $getWorkflowStaticData('global');
const eraOltre = !!state.oltre;
const scatta = oltre && !eraOltre;
state.oltre = oltre;
return [{ json: { scatta, prezzo, soglia, direzione, mint } }];
